      en: ["The range extends for a total length of approximately 125 kilometers.", "The highest peak is Illimani, reaching an elevation of 6,438 meters.", "At least six peaks within the range exceed 6,000 meters in height.", "The mountain range is primarily composed of granite and metamorphic rocks.", "Glaciers in the range have lost nearly 40% of their surface area since 1975.", "Huayna Potosí is often cited as one of the most climbed 6,000m peaks in the world."],
      es: ["Se encuentra en el territorio del Estado Plurinacional de Bolivia.", "Integrada entre la cordillera de los Andes, el Altiplano y las tierras bajas orientales.", "Desempeña un papel en la identidad local de la región.", "Conocida por su importancia paisajística o cultural.", "Vinculada al patrimonio cultural de los aymaras y quechuas.", "Gestionada por autoridades y comunidades locales.", "Relacionada con la tradición de extracción de litio, plata y gas natural."],
      pt: ["Situa-se no território do Estado Plurinacional da Bolívia.", "Inserida entre a cordilheira dos Andes, o Altiplano e as terras baixas orientais.", "Desempenha um papel na identidade local da região.", "Conhecida pela sua importância paisagística ou cultural.", "Ligada ao património cultural dos Aymara e Quechua.", "Gerida por autoridades e comunidades locais.", "Ligada à tradição de extração de lítio, prata e gás natural."],
      fr: ["Se situe sur le territoire de l'État plurinational de Bolivie.", "Nichée entre la cordillère des Andes, l'Altiplano et les basses terres orientales.", "Joue un rôle dans l'identité locale de la région.", "Connue pour son importance paysagère ou culturelle.", "Liée au patrimoine culturel des Aymaras et des Quechuas.", "Gérée par les autorités et les communautés locales.", "Associée à la tradition de l'extraction du lithium, de l'argent et du gaz naturel."],
