      hu: ["A Föld legnagyobb összefüggő trópusi szárazerdeje", "Eredeti kiterjedése meghaladta a 20 millió hektárt", "Több mint 1200 gerinces állatfaj él a területén", "A száraz évszak májustól szeptemberig tart", "Fontos ökológiai folyosó az Amazonas és a Chaco között", "A térségben találhatók az UNESCO világörökségi jezsuita missziók"],
      ro: ["Cea mai mare pădure tropicală uscată continuă de pe planetă", "Suprafață originală de peste 20 de milioane de hectare", "Găzduiește peste 1.200 de specii de vertebrate", "Sezonul uscat durează din mai până în septembrie", "Parte a coridorului ecologic între Amazonia și Gran Chaco", "Regiunea adăpostește misiunile iezuite protejate de UNESCO"],
      en: ["World's largest continuous block of tropical dry forest", "Original area exceeded 20 million hectares", "Home to more than 1,200 species of vertebrates", "Dry season typically lasts from May to September", "Acts as an ecological corridor between the Amazon and the Chaco", "The region contains UNESCO-listed Jesuit mission sites"],
