      en: "Pomerape, together with the neighboring Parinacota, forms the distinctive Payachata volcanic system.",
      es: "El Pomerape forma, junto con el vecino Parinacota, el destacado sistema volcánico Payachata.",
      pt: "O Pomerape, juntamente com o vizinho Parinacota, forma o impressionante sistema vulcânico Payachata.",
      fr: "Le Pomerape forme, avec le Parinacota voisin, le remarquable système volcanique des Payachata.",
