      es: ["Caída pronunciada (4.000 m)", "Energía para La Paz", "Flora endémica rica", "Región minera"],
      pt: ["Queda acentuada (até 4.000 m de altitude)", "Importante para a produção de energia em La Paz", "Flora rica em espécies endémicas", "Região mineira"],
      fr: ["Chute abrupte (4 000 m de dénivelé)", "Crucial pour l'électricité de La Paz", "Riche flore endémique", "Région minière"],
